"use client";
/**
 * Clio list: timed rows with a "next" chip on the first one still ahead. The rows settle in one after another once
 * the tile has risen; marking the next one done passes the chip down, and a row marked here can be undone.
 */
import { type ReactNode, useState } from "react";
import { ClioTile, type ClioTileProps, clioTileAliveDelay, useClioAlive } from "./theme";
import { CLIO_MOTION } from "./tokens";

const CSS = `
.clio-list__rows{list-style:none;margin:10px 0 0;padding:0;display:flex;flex-direction:column;gap:4px;min-height:0}
.clio-list__row{position:relative;display:grid;grid-template-columns:var(--clio-list-time,52px) 2px minmax(0,1fr) auto;align-items:start;column-gap:10px;padding:9px 10px 9px 8px;border-radius:var(--clio-radius-inner);opacity:0;transform:translate3d(0,8px,0);transition:opacity 520ms var(--clio-alive-ease),transform 640ms var(--clio-alive-ease),background-color 360ms var(--clio-mode-ease),box-shadow 360ms var(--clio-mode-ease);transition-delay:var(--clio-row-delay,0ms),var(--clio-row-delay,0ms),0ms,0ms}
.clio-list[data-alive] .clio-list__row{opacity:1;transform:none}
.clio-list__row[data-next]{background:var(--clio-raised);box-shadow:var(--clio-shadow-raised),0 0 0 1px var(--clio-hairline)}
.clio-list__time{padding-top:1px;font-family:var(--clio-mono);font-size:11px;line-height:1.4;font-variant-numeric:tabular-nums;color:var(--clio-ink-tertiary);white-space:nowrap;transition:color var(--clio-mode-ms) var(--clio-mode-ease)}
.clio-list__day{display:block}
.clio-list__rule{align-self:stretch;width:2px;border-radius:1px;background:var(--clio-hairline-strong);transition:background-color 360ms var(--clio-mode-ease)}
.clio-list__row[data-next] .clio-list__rule{background:var(--clio-accent)}
.clio-list__text{min-width:0;display:flex;flex-direction:column;gap:3px}
.clio-list__title{margin:0;font-size:13px;font-weight:500;line-height:1.3;letter-spacing:-.006em;color:var(--clio-ink);overflow:hidden;text-overflow:ellipsis;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;transition:color var(--clio-mode-ms) var(--clio-mode-ease)}
.clio-list__row[data-past] .clio-list__title,.clio-list__row[data-done] .clio-list__title{color:var(--clio-ink-tertiary)}
.clio-list__row[data-done] .clio-list__title{text-decoration:line-through;text-decoration-thickness:1px}
.clio-list__side{display:flex;flex-direction:column;align-items:flex-end;gap:8px}
.clio-list__chip{display:inline-flex;align-items:center;height:20px;padding:0 8px;border-radius:999px;background:var(--clio-accent);color:var(--clio-on-accent);font-family:var(--clio-mono);font-size:10.5px;line-height:1;white-space:nowrap;animation:clio-list-chip 420ms var(--clio-alive-ease) both;animation-delay:var(--clio-chip-delay,0ms);transition:background-color var(--clio-mode-ms) var(--clio-mode-ease)}
@keyframes clio-list-chip{from{opacity:0;transform:scale(.8)}to{opacity:1;transform:none}}
.clio-list__done{all:unset;cursor:pointer;font-size:12px;font-weight:500;line-height:1;color:var(--clio-accent-ink);border-radius:6px;padding:3px 2px;transition:color 160ms ease}
.clio-list__done:hover{color:var(--clio-ink)}
.clio-list__done:focus-visible{outline:2px solid var(--clio-accent);outline-offset:2px}
.clio-list__check{width:14px;height:14px;color:var(--clio-ink-tertiary)}
.clio-list__empty{margin:auto 0 0;padding-top:12px;font-size:13px;line-height:1.45;color:var(--clio-ink-secondary)}
@media (prefers-reduced-motion:reduce){.clio-list__row{opacity:1;transform:none;transition:background-color 200ms linear}.clio-list__chip{animation:none}}
`;

export interface ClioListItem {
  id: string;
  title: string;
  /** One mono line under the title. */
  detail?: string;
  /** When it is due: a Date, epoch milliseconds or an ISO date-time. */
  at: Date | number | string;
  /** The time as shown, e.g. "18:30". Formatted from `at` when left out. */
  time?: string;
  done?: boolean;
}

/** Epoch milliseconds of a Date, a number or an ISO string; NaN when it cannot be read. */
export const clioTimeOf = (at: Date | number | string): number =>
  at instanceof Date ? at.getTime() : typeof at === "number" ? at : Date.parse(at);

/** The next item: the earliest one not done whose time is now or later. None when everything is past. */
export function clioPickNext<T extends Pick<ClioListItem, "at" | "done">>(
  items: readonly T[],
  now: Date | number | string,
): T | null {
  const t = clioTimeOf(now);
  if (!Number.isFinite(t)) return null;
  let next: T | null = null;
  let nextAt = Number.POSITIVE_INFINITY;
  for (const item of items) {
    if (item.done) continue;
    const at = clioTimeOf(item.at);
    if (!Number.isFinite(at) || at < t) continue;
    if (at < nextAt) {
      next = item;
      nextAt = at;
    }
  }
  return next;
}

/** Whole minutes from now until `at`, rounded up. */
export const clioMinutesUntil = (at: Date | number | string, now: Date | number | string) =>
  Math.max(0, Math.ceil((clioTimeOf(at) - clioTimeOf(now)) / 60_000));

/** "Now", "In 25 min", "In 1 h 40 min", "In 3 days". */
export function clioUntilLabel(minutes: number): string {
  if (minutes < 1) return "Now";
  if (minutes < 60) return `In ${minutes} min`;
  if (minutes < 24 * 60) {
    const h = Math.floor(minutes / 60);
    const m = minutes % 60;
    return m ? `In ${h} h ${m} min` : `In ${h} h`;
  }
  const d = Math.round(minutes / (24 * 60));
  return d === 1 ? "In 1 day" : `In ${d} days`;
}

export interface ClioListProps extends Omit<ClioTileProps, "children" | "label"> {
  label?: ReactNode;
  items?: ClioListItem[];
  /** The time the next item is picked against. Null (before the page knows the time) picks none. */
  now?: Date | number | string | null;
  /** The chip on the next row. */
  nextLabel?: (minutes: number, item: ClioListItem) => string;
  /** The button on the next row; leave empty for none. */
  actionLabel?: string;
  /** Called when the next row's button is pressed. The list also marks it done itself. */
  onDone?: (id: string) => void;
  /** The button on a row marked done here, which takes the mark back; leave empty for none. */
  undoLabel?: string;
  /** Called when a row marked done here is undone. */
  onUndo?: (id: string) => void;
  /** Shown when the list is empty. */
  emptyText?: ReactNode;
  /** How many rows to show. */
  maxItems?: number;
  locale?: string;
  timeZone?: string;
  /** Settle the rows in after the rise. */
  animate?: boolean;
}

export function ClioList({
  label = "Reading queue",
  items = [],
  now = null,
  nextLabel = (minutes) => clioUntilLabel(minutes),
  actionLabel = "Mark read",
  onDone,
  undoLabel = "Undo",
  onUndo,
  emptyText = "Nothing waiting. Saves you queue show up here.",
  maxItems = 5,
  locale = "en-GB",
  timeZone,
  animate = true,
  riseIndex,
  riseDelay,
  className,
  meta,
  ...tile
}: ClioListProps) {
  const [doneIds, setDoneIds] = useState<ReadonlySet<string>>(() => new Set());
  // After a row is marked done the chip moves straight on; on arrival it waits for the rows to settle.
  const [handedOn, setHandedOn] = useState(false);
  const alive = useClioAlive(clioTileAliveDelay(riseIndex, riseDelay), animate);
  const rows = items
    .map((item) => ({ ...item, done: item.done || doneIds.has(item.id) }))
    .sort((a, b) => clioTimeOf(a.at) - clioTimeOf(b.at))
    .slice(0, Math.max(0, maxItems));
  const next = now === null ? null : clioPickNext(rows, now);
  const nowMs = now === null ? Number.NaN : clioTimeOf(now);
  const left = rows.filter((row) => !row.done).length;
  const clock = (row: ClioListItem) =>
    row.time ??
    new Intl.DateTimeFormat(locale, {
      hour: "2-digit",
      minute: "2-digit",
      hour12: false,
      ...(timeZone ? { timeZone } : {}),
    }).format(new Date(clioTimeOf(row.at)));
  // A row due on another day than now gets its weekday under the time, so tomorrow's 08:00 doesn't read as
  // earlier than today's 09:50.
  const zone = timeZone ? { timeZone } : {};
  const dayOf = (ms: number) =>
    new Intl.DateTimeFormat(locale, {
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      ...zone,
    }).format(new Date(ms));
  const today = Number.isFinite(nowMs) ? dayOf(nowMs) : null;
  const weekday = (row: ClioListItem) => {
    const ms = clioTimeOf(row.at);
    if (row.time !== undefined || today === null || !Number.isFinite(ms) || dayOf(ms) === today)
      return null;
    return new Intl.DateTimeFormat(locale, { weekday: "short", ...zone }).format(new Date(ms));
  };
  const markDone = (id: string) => {
    setDoneIds((before) => new Set(before).add(id));
    setHandedOn(true);
    onDone?.(id);
  };
  const undo = (id: string) => {
    setDoneIds((before) => {
      const after = new Set(before);
      after.delete(id);
      return after;
    });
    onUndo?.(id);
  };

  return (
    <ClioTile
      {...tile}
      label={label}
      meta={meta ?? (rows.length ? `${left} left` : null)}
      riseIndex={riseIndex}
      riseDelay={riseDelay}
      className={className ? `clio-list ${className}` : "clio-list"}
      data-alive={alive ? "" : undefined}
    >
      <style>{CSS}</style>
      {rows.length ? (
        <ol className="clio-list__rows">
          {rows.map((row, i) => {
            const isNext = next?.id === row.id;
            const past = Number.isFinite(nowMs) && clioTimeOf(row.at) < nowMs;
            const until =
              isNext && now !== null ? nextLabel(clioMinutesUntil(row.at, now), row) : null;
            const day = weekday(row);
            return (
              <li
                key={row.id}
                className="clio-list__row"
                aria-current={isNext ? "true" : undefined}
                data-next={isNext ? "" : undefined}
                data-done={row.done ? "" : undefined}
                data-past={past ? "" : undefined}
                style={{ ["--clio-row-delay" as string]: `${i * CLIO_MOTION.alive.stagger}ms` }}
              >
                <span className="clio-list__time">
                  {clock(row)}
                  {day ? <span className="clio-list__day">{day}</span> : null}
                </span>
                <span className="clio-list__rule" aria-hidden="true" />
                <span className="clio-list__text">
                  <span className="clio-list__title">
                    {row.title}
                    {row.done ? <span className="clio-sr">, done</span> : null}
                  </span>
                  {row.detail ? <span className="clio-caption">{row.detail}</span> : null}
                </span>
                <span className="clio-list__side">
                  {until && alive ? (
                    <span
                      className="clio-list__chip"
                      style={{
                        ["--clio-chip-delay" as string]: handedOn
                          ? "60ms"
                          : `${i * CLIO_MOTION.alive.stagger + 260}ms`,
                      }}
                    >
                      <span className="clio-sr">Next, </span>
                      {until}
                    </span>
                  ) : null}
                  {isNext && actionLabel ? (
                    <button
                      type="button"
                      className="clio-list__done"
                      onClick={() => markDone(row.id)}
                      aria-label={`${actionLabel}: ${row.title}`}
                    >
                      {actionLabel}
                    </button>
                  ) : null}
                  {row.done ? (
                    <svg className="clio-list__check" viewBox="0 0 14 14" aria-hidden="true">
                      <path
                        d="M3 7.4 5.8 10 11 4.4"
                        fill="none"
                        stroke="currentColor"
                        strokeWidth="1.4"
                        strokeLinecap="round"
                        strokeLinejoin="round"
                      />
                    </svg>
                  ) : null}
                  {doneIds.has(row.id) && undoLabel ? (
                    <button
                      type="button"
                      className="clio-list__done clio-list__undo"
                      onClick={() => undo(row.id)}
                      aria-label={`${undoLabel}: ${row.title}`}
                    >
                      {undoLabel}
                    </button>
                  ) : null}
                </span>
              </li>
            );
          })}
        </ol>
      ) : (
        <p className="clio-list__empty">{emptyText}</p>
      )}
    </ClioTile>
  );
}
